SourceCode.Declaration:
[DataContractAttribute]
class HSMobileOpsTransferResponse
{
    boolean          success;
    str              errorCode;
    str              message;
    str              transferId;
    str              transferStatus;
    boolean          actionable;
    InventSiteId     fromSiteId;
    InventLocationId fromWarehouseId;
    InventSiteId     toSiteId;
    InventLocationId toWarehouseId;
    int              outstandingLineCount;
    boolean          linesIncluded;
    List             lines;

    // Receive direction only - see HSMobileOpsProcessSetup.RequireLocationCapture and the
    // identical field on HSMobileOpsPurchOrderResponse. Shipping never asks for a location at
    // all, regardless of this flag - the source location is already on the line.
    boolean          requireLocationCapture;
    WMSLocationId    defaultIssueLocation;
    WMSLocationId    defaultReceiptLocation;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

/// <summary>
/// NOT_FOUND, WRONG_WAREHOUSE, NOT_SHIPPABLE, NOT_RECEIVABLE, NOTHING_OUTSTANDING,
/// INVALID_REQUEST.
///
/// WRONG_WAREHOUSE is worth its own code: an operator scanning a transfer at the wrong end is
/// the commonest mistake in this flow, and "nothing to do" would send them looking for a data
/// problem that is not there.
/// </summary>
[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('TransferId')]
public str parmTransferId(str _value = transferId)
{
    transferId = _value;
    return transferId;
}

[DataMemberAttribute('TransferStatus')]
public str parmTransferStatus(str _value = transferStatus)
{
    transferStatus = _value;
    return transferStatus;
}

/// <summary>
/// Whether the requested direction can be worked right now. Decided on the server from the
/// status enum, so the client never has to interpret a status string.
/// </summary>
[DataMemberAttribute('Actionable')]
public boolean parmActionable(boolean _value = actionable)
{
    actionable = _value;
    return actionable;
}

[DataMemberAttribute('FromSiteId')]
public InventSiteId parmFromSiteId(InventSiteId _value = fromSiteId)
{
    fromSiteId = _value;
    return fromSiteId;
}

[DataMemberAttribute('FromWarehouseId')]
public InventLocationId parmFromWarehouseId(InventLocationId _value = fromWarehouseId)
{
    fromWarehouseId = _value;
    return fromWarehouseId;
}

[DataMemberAttribute('ToSiteId')]
public InventSiteId parmToSiteId(InventSiteId _value = toSiteId)
{
    toSiteId = _value;
    return toSiteId;
}

[DataMemberAttribute('ToWarehouseId')]
public InventLocationId parmToWarehouseId(InventLocationId _value = toWarehouseId)
{
    toWarehouseId = _value;
    return toWarehouseId;
}

[DataMemberAttribute('OutstandingLineCount')]
public int parmOutstandingLineCount(int _value = outstandingLineCount)
{
    outstandingLineCount = _value;
    return outstandingLineCount;
}

/// <summary>
/// False when the order carries too many lines to send whole; the client then asks per item.
/// Same adaptive rule as purchase orders, for the same reason.
/// </summary>
[DataMemberAttribute('LinesIncluded')]
public boolean parmLinesIncluded(boolean _value = linesIncluded)
{
    linesIncluded = _value;
    return linesIncluded;
}

[DataMemberAttribute('Lines'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsTransferLineContract))]
public List parmLines(List _value = lines)
{
    lines = _value;
    return lines;
}

[DataMemberAttribute('RequireLocationCapture')]
public boolean parmRequireLocationCapture(boolean _value = requireLocationCapture)
{
    requireLocationCapture = _value;
    return requireLocationCapture;
}

/// <summary>The warehouse master's default issue location - the bin the app uses unless another is scanned.</summary>
[DataMemberAttribute('DefaultIssueLocation')]
public WMSLocationId parmDefaultIssueLocation(WMSLocationId _value = defaultIssueLocation)
{
    defaultIssueLocation = _value;
    return defaultIssueLocation;
}

/// <summary>The warehouse master's default receipt location - the bin the app uses unless another is scanned.</summary>
[DataMemberAttribute('DefaultReceiptLocation')]
public WMSLocationId parmDefaultReceiptLocation(WMSLocationId _value = defaultReceiptLocation)
{
    defaultReceiptLocation = _value;
    return defaultReceiptLocation;
}
